args.content:
/*
 * Integrity checks for the xz reimplementation: CRC32 (IEEE), CRC64
 * (ECMA-182, reflected), and SHA-256, as used by the .xz format.
 *
 * All functions are one-shot over a memory buffer.
 */
#ifndef MYXZ_CHECK_H
#define MYXZ_CHECK_H

#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>

/* Check IDs as stored in the .xz stream flags. */
#define CHECK_ID_NONE   0x00
#define CHECK_ID_CRC32  0x01
#define CHECK_ID_CRC64  0x04
#define CHECK_ID_SHA256 0x0A
#define CHECK_ID_MAX    0x0F

/*
 * Size of the check field for a check ID. IDs 0x00-0x0F have a defined
 * size per the .xz spec: 0x00->0, 0x01->4, 0x02->4, 0x03->4, 0x04->8,
 * 0x05->8, 0x06->8, 0x07->16, 0x08->16, 0x09->16, 0x0A->32, 0x0B->32,
 * 0x0C->32, 0x0D->64, 0x0E->64, 0x0F->64. Returns -1 for id > 0x0F.
 */
int check_size_by_id(int id);

/* True for IDs this implementation can actually verify:
 * none, crc32, crc64, sha256. */
bool check_id_supported(int id);

/* Compute the check of the given type over buf. out must have room for
 * check_size_by_id(id) bytes. Only supported IDs may be passed. */
void check_compute(int id, const uint8_t *buf, size_t len, uint8_t *out);

/* Individual algorithms (little-endian byte order output for CRCs,
 * big-endian for SHA-256, matching the .xz spec). */
uint32_t my_crc32(const uint8_t *buf, size_t len, uint32_t crc);
uint64_t my_crc64(const uint8_t *buf, size_t len, uint64_t crc);
void my_sha256(const uint8_t *buf, size_t len, uint8_t out[32]);

#endif

/*
 * Delta and BCJ ("simple") filters, both directions, in place over a
 * memory buffer.
 */
#ifndef MYXZ_FILTERS_H
#define MYXZ_FILTERS_H

#include <stddef.h>
#include <stdint.h>

/* Filter IDs as stored in .xz block headers. */
#define FILTER_ID_X86       0x04
#define FILTER_ID_POWERPC   0x05
#define FILTER_ID_IA64      0x06
#define FILTER_ID_ARM       0x07
#define FILTER_ID_ARMTHUMB  0x08
#define FILTER_ID_SPARC     0x09
#define FILTER_ID_ARM64     0x0A
#define FILTER_ID_RISCV     0x0B
#define FILTER_ID_DELTA     0x03
#define FILTER_ID_LZMA1     0x4000000000000001ULL
#define FILTER_ID_LZMA2     0x21

/* Delta filter, distance 1..256. In place. */
void delta_encode(uint8_t *buf, size_t size, uint32_t dist);
void delta_decode(uint8_t *buf, size_t size, uint32_t dist);

/*
 * BCJ filters. start_offset is the filter's start offset option.
 * Both directions work in place. They return 0 on success; non-zero if
 * the filter ID is unknown.
 */
int bcj_encode(uint8_t *buf, size_t size, uint64_t filter_id,
               uint32_t start_offset);
int bcj_decode(uint8_t *buf, size_t size, uint64_t filter_id,
               uint32_t start_offset);

#endif

/*
 * .xz container: stream header/footer, blocks, index, padding.
 * Buffer based, single or concatenated streams.
 *
 * Encoding is two-stage: the caller compresses each block's payload
 * (e.g. an LZMA2 stream) and this module assembles the container,
 * computing block checks from the uncompressed data.
 */
#ifndef MYXZ_XZFILE_H
#define MYXZ_XZFILE_H

#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>

/* A filter in a block's filter chain. */
typedef struct {
    uint64_t id;            /* FILTER_ID_* from filters.h */
    uint8_t props[16];
    uint8_t props_size;     /* 0..16 */
} filter_spec;

/* One compressed block ready for container assembly. */
typedef struct {
    const uint8_t *uncomp;
    size_t uncomp_size;
    const uint8_t *comp;    /* raw payload, e.g. LZMA2 stream w/ 0x00 end */
    size_t comp_size;
} block_data;

/*
 * Assemble one complete .xz stream.
 * check_id: CHECK_ID_* from check.h.
 * store_sizes: when true, each block header contains the compressed and
 *   uncompressed sizes (multithreaded encoder behavior).
 * Returns 0 on success, nonzero if out_cap too small.
 */
int xz_assemble(const block_data *blocks, size_t nblocks,
                const filter_spec *filters, size_t nfilters,
                int check_id, bool store_sizes,
                uint8_t *out, size_t out_cap, size_t *out_len);

/* Worst-case bound for xz_assemble output. */
size_t xz_assemble_bound(const block_data *blocks, size_t nblocks,
                         size_t nfilters, int check_id);

/* Decoder result codes. */
#define XZD_OK            0
#define XZD_FORMAT        1   /* not a recognized format (bad magic etc.) */
#define XZD_OPTIONS       2   /* unsupported option (reserved flag bits,
                               * unsupported filter, bad VLI, ...) */
#define XZD_DATA          3   /* corrupt data */
#define XZD_EOF           4   /* unexpected end of input */
#define XZD_CHECK         5   /* integrity check mismatch */
#define XZD_MEMLIMIT      6   /* memory usage limit exceeded */

typedef struct {
    int code;               /* XZD_* */
    uint8_t *out;           /* malloc'd decompressed data (NULL on error) */
    size_t out_size;
    size_t consumed;        /* input bytes of valid stream(s) processed */
    bool trailing_garbage;  /* extra nonzero junk after last stream */
    int check_id;           /* check used by (first) stream, -1 if none */
    bool unsupported_check; /* check ID unknown: not verified */
    uint32_t stream_flags;  /* reserved-flag info for diagnostics */
    bool used_lzip;         /* input was .lz format */
} xz_dec_result;

/*
 * Decode one or more concatenated .xz streams from memory.
 * single_stream: stop after the first stream, ignore the rest silently.
 * ignore_check: skip verification of the integrity check.
 * The result fields are always filled; res->out is malloc'd (caller frees)
 * even on some error paths it may be NULL.
 *
 * This also detects the .lz (lzip) format and decodes it (single member
 * or concatenated members) when format detection is left to auto.
 */
int xz_decode_mem(const uint8_t *in, size_t in_size, xz_dec_result *res,
                  bool single_stream, bool ignore_check);

/*
 * VLI helpers (used by index/headers). multibyte integer per .xz spec.
 * vli_encode writes at most 9 bytes, returns count. vli_decode returns
 * bytes consumed or 0 on error (invalid/truncated); sets *v.
 */
size_t vli_encode(uint64_t v, uint8_t *out);
size_t vli_decode(const uint8_t *in, size_t avail, uint64_t *v);

#endif

/*
 * Container formats: .xz (stream header/footer, blocks, index, padding),
 * legacy .lzma ("alone"), and .lz (lzip, decode only).
 * Buffer based.
 *
 * .xz encoding is two-stage: the caller compresses each block's payload
 * (e.g. an LZMA2 stream) and this module assembles the container,
 * computing block checks from the uncompressed data.
 */
#ifndef MYXZ_XZFILE_H
#define MYXZ_XZFILE_H

#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>

/* A filter in a block's filter chain. */
typedef struct {
    uint64_t id;            /* FILTER_ID_* from filters.h */
    uint8_t props[16];
    uint8_t props_size;     /* 0..16 */
} filter_spec;

/* One compressed block ready for container assembly. */
typedef struct {
    const uint8_t *uncomp;
    size_t uncomp_size;
    const uint8_t *comp;    /* raw payload, e.g. LZMA2 stream w/ 0x00 end */
    size_t comp_size;
} block_data;

/*
 * Assemble one complete .xz stream.
 * check_id: CHECK_ID_* from check.h.
 * store_sizes: when true, each block header contains the compressed and
 *   uncompressed sizes (multithreaded encoder behavior).
 * Returns 0 on success, nonzero if out_cap too small.
 */
int xz_assemble(const block_data *blocks, size_t nblocks,
                const filter_spec *filters, size_t nfilters,
                int check_id, bool store_sizes,
                uint8_t *out, size_t out_cap, size_t *out_len);

/* Worst-case bound for xz_assemble output. */
size_t xz_assemble_bound(const block_data *blocks, size_t nblocks,
                         size_t nfilters, int check_id);

/* Decoder result codes. */
#define XZD_OK            0
#define XZD_FORMAT        1   /* not a recognized format (bad magic etc.) */
#define XZD_OPTIONS       2   /* unsupported option (reserved flag bits,
                               * unsupported filter, bad props, ...) */
#define XZD_DATA          3   /* corrupt data */
#define XZD_EOF           4   /* unexpected end of input */
#define XZD_CHECK         5   /* integrity check mismatch */
#define XZD_MEMLIMIT      6   /* memory usage limit exceeded */

/* Format detection results. */
#define XZF_UNKNOWN 0
#define XZF_XZ      1
#define XZF_LZMA    2
#define XZF_LZIP    3

typedef struct {
    int code;               /* XZD_* */
    uint8_t *out;           /* malloc'd decompressed data, possibly partial
                             * (caller frees, may be NULL) */
    size_t out_size;
    size_t consumed;        /* input bytes consumed */
    bool trailing_garbage;  /* extra junk after last stream/member */
    int check_id;           /* check used by (first) xz stream, -1 else */
    bool unsupported_check; /* check ID unknown: not verified */
    int format;             /* XZF_* detected/used */
} xz_dec_result;

/* Sniff the format of a buffer (auto mode rules). */
int xz_detect_format(const uint8_t *in, size_t in_size);

/*
 * Decode one or more concatenated .xz streams from memory.
 * single_stream: stop after the first stream, ignore the rest silently.
 * ignore_check: skip verification of the integrity check.
 * res fields are always filled; res->out is malloc'd (caller frees) and
 * may hold partial output when an error occurred after some blocks were
 * decoded.
 */
int xz_decode_xz(const uint8_t *in, size_t in_size, xz_dec_result *res,
                 bool single_stream, bool ignore_check);

/* Decode a .lzma (alone) file: 13-byte header + LZMA1 stream.
 * allow_trailing: extra data after the stream sets trailing_garbage. */
int xz_decode_lzma(const uint8_t *in, size_t in_size, xz_dec_result *res);

/* Decode one or more concatenated .lz (lzip) members. */
int xz_decode_lzip(const uint8_t *in, size_t in_size, xz_dec_result *res);

/*
 * VLI helpers (multibyte integers per .xz spec).
 * vli_encode writes at most 9 bytes, returns count.
 * vli_decode returns bytes consumed or 0 on error; sets *v.
 */
size_t vli_encode(uint64_t v, uint8_t *out);
size_t vli_decode(const uint8_t *in, size_t avail, uint64_t *v);

#endif

/*
 * Container formats implementation: .xz, .lzma (alone), .lz (lzip).
 * See doc/xz-file-format.txt and doc/lzma-file-format.txt.
 */
#include <stdlib.h>
#include <string.h>

#include "xzfile.h"
#include "check.h"
#include "filters.h"
#include "lzma_dec.h"

static const uint8_t XZ_HEADER_MAGIC[6] = { 0xFD, '7', 'z', 'X', 'Z', 0x00 };
static const uint8_t XZ_FOOTER_MAGIC[2] = { 'Y', 'Z' };

static uint32_t get_le32(const uint8_t *p)
{
    return (uint32_t)p[0] | ((uint32_t)p[1] << 8)
            | ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}

static uint64_t get_le64(const uint8_t *p)
{
    return (uint64_t)get_le32(p) | ((uint64_t)get_le32(p + 4) << 32);
}

static void put_le32(uint8_t *p, uint32_t v)
{
    p[0] = (uint8_t)v;
    p[1] = (uint8_t)(v >> 8);
    p[2] = (uint8_t)(v >> 16);
    p[3] = (uint8_t)(v >> 24);
}

size_t vli_encode(uint64_t v, uint8_t *out)
{
    size_t i = 0;

    if (v > UINT64_MAX / 2)
        return 0;

    while (v >= 0x80) {
        out[i++] = (uint8_t)v | 0x80;
        v >>= 7;
    }
    out[i++] = (uint8_t)v;
    return i;
}

size_t vli_decode(const uint8_t *in, size_t avail, uint64_t *v)
{
    if (avail == 0)
        return 0;

    if (avail > 9)
        avail = 9;

    *v = in[0] & 0x7F;
    size_t i = 0;

    while (in[i++] & 0x80) {
        if (i >= avail || in[i] == 0x00)
            return 0;

        *v |= (uint64_t)(in[i] & 0x7F) << (i * 7);
    }

    return i;
}

/* ---------------------------------------------------------------- */
/* .xz encoding                                                      */
/* ---------------------------------------------------------------- */

size_t xz_assemble_bound(const block_data *blocks, size_t nblocks,
                         size_t nfilters, int check_id)
{
    size_t total = 12 + 12 + 16;    /* header, footer, index base */
    int csize = check_size_by_id(check_id);
    if (csize < 0)
        csize = 0;

    for (size_t i = 0; i < nblocks; i++) {
        total += 8 + 18 + nfilters * (2 + 16 + 2) + 8; /* block header max */
        total += blocks[i].comp_size + 3 + (size_t)csize + 3;
        total += 18;                /* index record max */
    }
    return total + 64;
}

int xz_assemble(const block_data *blocks, size_t nblocks,
                const filter_spec *filters, size_t nfilters,
                int check_id, bool store_sizes,
                uint8_t *out, size_t out_cap, size_t *out_len)
{
    if (nfilters < 1 || nfilters > 4)
        return 1;

    int csize = check_size_by_id(check_id);
    if (csize < 0)
        return 1;

    size_t pos = 0;

    /* Stream Header */
    if (out_cap < 12)
        return 1;
    memcpy(out, XZ_HEADER_MAGIC, 6);
    out[6] = 0x00;
    out[7] = (uint8_t)check_id;
    uint8_t crc[4];
    check_compute(CHECK_ID_CRC32, out + 6, 2, crc);
    put_le32(out + 8, get_le32(crc));
    pos = 12;

    /* Index records are collected while writing blocks. */
    uint64_t *rec_unpadded = malloc(nblocks * sizeof(uint64_t) + 8);
    uint64_t *rec_uncomp = malloc(nblocks * sizeof(uint64_t) + 8);
    if (rec_unpadded == NULL || rec_uncomp == NULL) {
        free(rec_unpadded);
        free(rec_uncomp);
        return 1;
    }

    for (size_t bi = 0; bi < nblocks; bi++) {
        /* Compute block header size. */
        size_t hdr = 2;             /* size byte + flags */
        uint8_t tmp[18];
        if (store_sizes) {
            hdr += vli_encode(blocks[bi].comp_size, tmp);
            hdr += vli_encode(blocks[bi].uncomp_size, tmp);
        }
        for (size_t fi = 0; fi < nfilters; fi++) {
            hdr += vli_encode(filters[fi].id, tmp);
            hdr += vli_encode(filters[fi].props_size, tmp);
            hdr += filters[fi].props_size;
        }
        hdr += 4;                   /* CRC32 */
        size_t hdr_padded = (hdr + 3) & ~(size_t)3;
        if (hdr_padded < 8)
            hdr_padded = 8;

        size_t unpadded = hdr_padded + blocks[bi].comp_size + (size_t)csize;
        size_t block_total = (unpadded + 3) & ~(size_t)3;

        if (pos + block_total > out_cap) {
            free(rec_unpadded);
            free(rec_uncomp);
            return 1;
        }

        uint8_t *h = out + pos;
        size_t hp = 0;
        h[hp++] = (uint8_t)(hdr_padded / 4 - 1);
        uint8_t flags = (uint8_t)(nfilters - 1);
        if (store_sizes)
            flags |= 0xC0;
        h[hp++] = flags;
        if (store_sizes) {
            hp += vli_encode(blocks[bi].comp_size, h + hp);
            hp += vli_encode(blocks[bi].uncomp_size, h + hp);
        }
        for (size_t fi = 0; fi < nfilters; fi++) {
            hp += vli_encode(filters[fi].id, h + hp);
            hp += vli_encode(filters[fi].props_size, h + hp);
            memcpy(h + hp, filters[fi].props, filters[fi].props_size);
            hp += filters[fi].props_size;
        }
        while (hp < hdr_padded - 4)
            h[hp++] = 0x00;
        check_compute(CHECK_ID_CRC32, h, hdr_padded - 4, crc);
        put_le32(h + hp, get_le32(crc));
        pos += hdr_padded;

        /* Compressed data */
        memcpy(out + pos, blocks[bi].comp, blocks[bi].comp_size);
        pos += blocks[bi].comp_size;

        /* Block padding */
        while ((pos & 3) != 0)
            out[pos++] = 0x00;

        /* Check */
        if (csize > 0) {
            check_compute(check_id, blocks[bi].uncomp,
                          blocks[bi].uncomp_size, out + pos);
            pos += (size_t)csize;
        }

        rec_unpadded[bi] = unpadded;
        rec_uncomp[bi] = blocks[bi].uncomp_size;
    }

    /* Index */
    size_t index_start = pos;
    if (pos + 4 + nblocks * 18 + 8 > out_cap) {
        free(rec_unpadded);
        free(rec_uncomp);
        return 1;
    }
    out[pos++] = 0x00;              /* index indicator */
    pos += vli_encode(nblocks, out + pos);
    for (size_t i = 0; i < nblocks; i++) {
        pos += vli_encode(rec_unpadded[i], out + pos);
        pos += vli_encode(rec_uncomp[i], out + pos);
    }
    while (((pos - index_start) & 3) != 0)
        out[pos++] = 0x00;
    check_compute(CHECK_ID_CRC32, out + index_start, pos - index_start, crc);
    put_le32(out + pos, get_le32(crc));
    pos += 4;
    size_t index_size = pos - index_start;

    free(rec_unpadded);
    free(rec_uncomp);

    /* Stream Footer */
    if (pos + 12 > out_cap)
        return 1;
    uint8_t back[6];
    put_le32(back, (uint32_t)(index_size / 4 - 1));
    back[4] = 0x00;
    back[5] = (uint8_t)check_id;
    check_compute(CHECK_ID_CRC32, back, 6, crc);
    put_le32(out + pos, get_le32(crc));
    memcpy(out + pos + 4, back, 6);
    out[pos + 10] = XZ_FOOTER_MAGIC[0];
    out[pos + 11] = XZ_FOOTER_MAGIC[1];
    pos += 12;

    *out_len = pos;
    return 0;
}

/* ---------------------------------------------------------------- */
/* Common decode helpers                                             */
/* ---------------------------------------------------------------- */

static void res_init(xz_dec_result *res)
{
    memset(res, 0, sizeof(*res));
    res->check_id = -1;
    res->format = XZF_UNKNOWN;
}

/* Append data to the result buffer. Returns false on allocation failure
 * (treated as data error by callers; sizes here are bounded by input). */
static bool res_append(xz_dec_result *res, const uint8_t *data, size_t size)
{
    if (size == 0)
        return true;

    uint8_t *nbuf = realloc(res->out, res->out_size + size);
    if (nbuf == NULL)
        return false;

    memcpy(nbuf + res->out_size, data, size);
    res->out = nbuf;
    res->out_size += size;
    return true;
}

/* ---------------------------------------------------------------- */
/* .xz decoding                                                      */
/* ---------------------------------------------------------------- */

/* Validate a filter chain from a block header and extract what the
 * decoder needs. Returns XZD_OK or an error code. */
static int validate_filters(const filter_spec *filters, size_t nfilters,
                            uint32_t *dict_size, unsigned *lc,
                            unsigned *lp, unsigned *pb)
{
    if (nfilters < 1 || nfilters > 4)
        return XZD_OPTIONS;

    /* Last filter must be LZMA2. */
    const filter_spec *last = &filters[nfilters - 1];
    if (last->id != FILTER_ID_LZMA2 || last->props_size != 1)
        return XZD_OPTIONS;

    uint8_t b = last->props[0];
    if (b & 0xC0)
        return XZD_OPTIONS;
    b &= 0x3F;
    if (b > 40)
        return XZD_OPTIONS;
    if (b == 40)
        *dict_size = UINT32_MAX;
    else
        *dict_size = (uint32_t)(2 | (b & 1)) << (b / 2 + 11);

    *lc = 3;
    *lp = 0;
    *pb = 2;

    /* Non-last filters: delta or BCJ, each at most once. */
    bool seen_delta = false;
    bool seen_bcj = false;
    for (size_t i = 0; i + 1 < nfilters; i++) {
        const filter_spec *f = &filters[i];
        if (f->id == FILTER_ID_DELTA) {
            if (f->props_size != 1 || seen_delta)
                return XZD_OPTIONS;
            seen_delta = true;
        } else if (f->id >= FILTER_ID_X86 && f->id <= FILTER_ID_RISCV) {
            if (seen_bcj)
                return XZD_OPTIONS;
            if (f->props_size != 0 && f->props_size != 4)
                return XZD_OPTIONS;
            if (f->props_size == 4) {
                static const uint32_t align[] = {
                    0, 0, 0, 0, 1, 4, 16, 4, 2, 4, 4, 2
                };
                uint32_t start = get_le32(f->props);
                if (start % align[f->id] != 0)
                    return XZD_OPTIONS;
            }
            seen_bcj = true;
        } else {
            return XZD_OPTIONS;
        }
    }

    return XZD_OK;
}

typedef struct {
    filter_spec filters[4];
    size_t nfilters;
    bool has_comp_size;
    bool has_uncomp_size;
    uint64_t comp_size;
    uint64_t uncomp_size;
    size_t header_size;
} block_header;

/* Parse a block header whose first byte (nonzero) is at in[*pos].
 * Consumes the full header on success. */
static int parse_block_header(const uint8_t *in, size_t in_size,
                              size_t *pos, block_header *bh)
{
    size_t p = *pos;
    size_t remaining = in_size - p;

    size_t header_size = ((size_t)in[p] + 1) * 4;
    if (remaining < header_size)
        return XZD_EOF;

    /* Verify CRC32 over everything but the CRC32 field itself. */
    uint8_t crc[4];
    check_compute(CHECK_ID_CRC32, in + p, header_size - 4, crc);
    if (get_le32(in + p + header_size - 4) != get_le32(crc))
        return XZD_DATA;

    uint8_t flags = in[p + 1];
    if (flags & 0x3C)
        return XZD_OPTIONS;

    bh->nfilters = (flags & 0x03) + 1;
    bh->has_comp_size = (flags & 0x40) != 0;
    bh->has_uncomp_size = (flags & 0x80) != 0;
    bh->header_size = header_size;

    size_t q = p + 2;
    size_t hend = p + header_size - 4;

    if (bh->has_comp_size) {
        size_t n = vli_decode(in + q, hend - q, &bh->comp_size);
        if (n == 0 || bh->comp_size == 0)
            return n == 0 && hend - q > 0 ? XZD_DATA : XZD_DATA;
        q += n;
    }
    if (bh->has_uncomp_size) {
        size_t n = vli_decode(in + q, hend - q, &bh->uncomp_size);
        if (n == 0)
            return XZD_DATA;
        q += n;
    }

    for (size_t i = 0; i < bh->nfilters; i++) {
        uint64_t id, psize;
        size_t n = vli_decode(in + q, hend - q, &id);
        if (n == 0)
            return XZD_DATA;
        q += n;
        n = vli_decode(in + q, hend - q, &psize);
        if (n == 0)
            return XZD_DATA;
        q += n;
        if (psize > hend - q || psize > 16)
            return psize > 16 ? XZD_OPTIONS : XZD_DATA;
        bh->filters[i].id = id;
        bh->filters[i].props_size = (uint8_t)psize;
        memcpy(bh->filters[i].props, in + q, psize);
        q += psize;
    }

    /* Header padding must be null bytes. */
    while (q < hend) {
        if (in[q] != 0x00)
            return XZD_DATA;
        q++;
    }

    *pos = p + header_size;
    return XZD_OK;
}

/* Decode one stream starting at in[*pos]. On success *pos is advanced
 * past the stream footer. Decoded data is appended to res->out as blocks
 * complete (so partial output is kept on error, like streaming does). */
static int decode_one_stream(const uint8_t *in, size_t in_size,
                             size_t *pos, xz_dec_result *res,
                             bool ignore_check, bool first_stream)
{
    size_t p = *pos;

    /* Stream Header */
    if (in_size - p < 12)
        return XZD_EOF;
    if (memcmp(in + p, XZ_HEADER_MAGIC, 6) != 0)
        return first_stream ? XZD_FORMAT : XZD_DATA;

    uint8_t flag0 = in[p + 6];
    uint8_t flag1 = in[p + 7];
    uint8_t crc[4];
    check_compute(CHECK_ID_CRC32, in + p + 6, 2, crc);
    if (get_le32(in + p + 8) != get_le32(crc))
        return XZD_DATA;
    if (flag0 != 0x00 || (flag1 & 0xF0) != 0)
        return XZD_OPTIONS;

    int check_id = flag1 & 0x0F;
    if (first_stream)
        res->check_id = check_id;
    bool supported = check_id_supported(check_id);
    if (!supported)
        res->unsupported_check = true;
    int csize = check_size_by_id(check_id);
    p += 12;

    /* Records for index verification. */
    uint64_t *rec_unpadded = NULL;
    uint64_t *rec_uncomp = NULL;
    size_t nrec = 0, rec_cap = 0;
    int ret = XZD_OK;

    /* Blocks */
    for (;;) {
        if (in_size - p < 1) {
            ret = XZD_EOF;
            break;
        }
        if (in[p] == 0x00)
            break;                  /* index begins */

        block_header bh;
        ret = parse_block_header(in, in_size, &p, &bh);
        if (ret != XZD_OK)
            break;

        uint32_t dict_size;
        unsigned lc, lp, pb;
        ret = validate_filters(bh.filters, bh.nfilters,
                               &dict_size, &lc, &lp, &pb);
        if (ret != XZD_OK)
            break;

        /* Decode the block payload (LZMA2). */
        size_t payload_avail;
        if (bh.has_comp_size) {
            if (bh.comp_size > in_size - p) {
                ret = XZD_EOF;
                break;
            }
            payload_avail = (size_t)bh.comp_size;
        } else {
            payload_avail = in_size - p;
        }

        size_t out_cap;
        uint8_t *buf;
        if (bh.has_uncomp_size) {
            out_cap = (size_t)bh.uncomp_size;
        } else {
            out_cap = payload_avail * 4 + (1 << 20);
        }
        buf = malloc(out_cap + 1);
        if (buf == NULL) {
            ret = XZD_DATA;
            break;
        }

        size_t in_pos = p;
        size_t out_len = 0;
        int lzret;
        for (;;) {
            lzret = lzma2_decode(in, p + payload_avail, &in_pos,
                                 buf, out_cap, &out_len,
                                 dict_size, lc, lp, pb);
            if (lzret != LZD_BUF)
                break;
            /* Output buffer too small: grow and retry. */
            out_cap *= 2;
            uint8_t *nbuf = realloc(buf, out_cap + 1);
            if (nbuf == NULL) {
                lzret = LZD_DATA;
                break;
            }
            buf = nbuf;
            in_pos = p;
            out_len = 0;
        }

        if (lzret == LZD_EOF) {
            free(buf);
            ret = XZD_EOF;
            break;
        }
        if (lzret != LZD_OK) {
            free(buf);
            ret = XZD_DATA;
            break;
        }

        size_t consumed = in_pos - p;
        if (bh.has_comp_size && consumed != bh.comp_size) {
            free(buf);
            ret = XZD_DATA;
            break;
        }
        if (bh.has_uncomp_size && out_len != bh.uncomp_size) {
            free(buf);
            ret = XZD_DATA;
            break;
        }
        p = in_pos;

        /* Block padding: null bytes to a multiple of four. */
        size_t bsize_no_pad = bh.header_size + consumed;
        size_t pad = (4 - (bsize_no_pad & 3)) & 3;
        if (in_size - p < pad + (size_t)csize) {
            free(buf);
            ret = XZD_EOF;
            break;
        }
        for (size_t i = 0; i < pad; i++) {
            if (in[p + i] != 0x00) {
                free(buf);
                ret = XZD_DATA;
                goto stream_done;
            }
        }
        p += pad;

        /* Undo the non-last filters, in reverse order. */
        for (size_t i = bh.nfilters - 1; i-- > 0; ) {
            const filter_spec *f = &bh.filters[i];
            if (f->id == FILTER_ID_DELTA) {
                delta_decode(buf, out_len, (uint32_t)f->props[0] + 1);
            } else {
                uint32_t start = f->props_size == 4
                        ? get_le32(f->props) : 0;
                bcj_decode(buf, out_len, f->id, start);
            }
        }

        /* Emit the block's data before verifying its check, matching
         * streaming behavior (partial output on check failure). */
        if (!res_append(res, buf, out_len)) {
            free(buf);
            ret = XZD_DATA;
            break;
        }

        /* Verify the check. */
        if (csize > 0) {
            if (supported && !ignore_check) {
                uint8_t actual[32];
                check_compute(check_id, res->out + res->out_size - out_len,
                              out_len, actual);
                if (memcmp(actual, in + p, (size_t)csize) != 0) {
                    free(buf);
                    ret = XZD_CHECK;
                    break;
                }
            }
            p += (size_t)csize;
        }

        free(buf);

        /* Record for index verification. */
        if (nrec == rec_cap) {
            rec_cap = rec_cap == 0 ? 16 : rec_cap * 2;
            rec_unpadded = realloc(rec_unpadded,
                                   rec_cap * sizeof(uint64_t));
            rec_uncomp = realloc(rec_uncomp, rec_cap * sizeof(uint64_t));
            if (rec_unpadded == NULL || rec_uncomp == NULL) {
                ret = XZD_DATA;
                break;
            }
        }
        rec_unpadded[nrec] = bh.header_size + consumed + (size_t)csize;
        rec_uncomp[nrec] = out_len;
        nrec++;
    }

stream_done:
    if (ret != XZD_OK)
        goto out;

    /* Index */
    {
        size_t index_start = p;
        p++;                        /* 0x00 indicator */
        uint64_t count;
        size_t n = vli_decode(in + p, in_size - p, &count);
        if (n == 0) {
            ret = in_size - p == 0 ? XZD_EOF : XZD_DATA;
            goto out;
        }
        if (in_size - p < n) {
            ret = XZD_EOF;
            goto out;
        }
        p += n;
        if (count != nrec) {
            ret = XZD_DATA;
            goto out;
        }
        for (size_t i = 0; i < nrec; i++) {
            uint64_t unpadded, uncomp;
            n = vli_decode(in + p, in_size - p, &unpadded);
            if (n == 0) {
                ret = in_size - p < 9 ? XZD_EOF : XZD_DATA;
                goto out;
            }
            p += n;
            n = vli_decode(in + p, in_size - p, &uncomp);
            if (n == 0) {
                ret = in_size - p < 9 ? XZD_EOF : XZD_DATA;
                goto out;
            }
            p += n;
            if (unpadded != rec_unpadded[i] || uncomp != rec_uncomp[i]) {
                ret = XZD_DATA;
                goto out;
            }
        }
        /* Index padding */
        while (((p - index_start) & 3) != 0) {
            if (in_size - p < 1) {
                ret = XZD_EOF;
                goto out;
            }
            if (in[p] != 0x00) {
                ret = XZD_DATA;
                goto out;
            }
            p++;
        }
        if (in_size - p < 4) {
            ret = XZD_EOF;
            goto out;
        }
        check_compute(CHECK_ID_CRC32, in + index_start,
                      p - index_start, crc);
        if (get_le32(in + p) != get_le32(crc)) {
            ret = XZD_DATA;
            goto out;
        }
        p += 4;
        size_t index_size = p - index_start;

        /* Stream Footer */
        if (in_size - p < 12) {
            ret = XZD_EOF;
            goto out;
        }
        check_compute(CHECK_ID_CRC32, in + p + 4, 6, crc);
        if (get_le32(in + p) != get_le32(crc)) {
            ret = XZD_DATA;
            goto out;
        }
        if (get_le32(in + p + 4) != (uint32_t)(index_size / 4 - 1)) {
            ret = XZD_DATA;
            goto out;
        }
        if (in[p + 8] != flag0 || in[p + 9] != flag1) {
            ret = XZD_DATA;
            goto out;
        }
        if (memcmp(in + p + 10, XZ_FOOTER_MAGIC, 2) != 0) {
            ret = XZD_DATA;
            goto out;
        }
        p += 12;
    }

out:
    free(rec_unpadded);
    free(rec_uncomp);
    *pos = p;
    return ret;
}

int xz_decode_xz(const uint8_t *in, size_t in_size, xz_dec_result *res,
                 bool single_stream, bool ignore_check)
{
    res_init(res);
    res->format = XZF_XZ;

    size_t p = 0;
    bool first = true;
    int ret = XZD_OK;

    for (;;) {
        if (!first) {
            /* Stream padding: null bytes, multiple of four. */
            size_t pad_start = p;
            while (p < in_size && in[p] == 0x00)
                p++;
            size_t pad = p - pad_start;
            if ((pad & 3) != 0) {
                if (p == in_size) {
                    /* Ends with padding that is not a multiple of 4. */
                    ret = XZD_DATA;
                } else {
                    /* Non-null byte at a non-aligned position. */
                    ret = XZD_DATA;
                }
                break;
            }
            if (p == in_size)
                break;              /* clean end */
        }

        if (single_stream && !first)
            break;

        if (in_size - p < 12 && !first) {
            /* Not enough bytes for another stream header. */
            if (in_size - p > 0)
                ret = XZD_EOF;
            break;
        }

        ret = decode_one_stream(in, in_size, &p, res, ignore_check, first);
        if (ret != XZD_OK)
            break;

        first = false;
        if (single_stream)
            break;
        if (p == in_size)
            break;
    }

    res->consumed = p;
    res->code = ret;
    return ret;
}

/* ---------------------------------------------------------------- */
/* Format detection                                                  */
/* ---------------------------------------------------------------- */

static bool lzma_props_valid(uint8_t b, unsigned *lc, unsigned *lp,
                             unsigned *pb)
{
    if (b >= 9 * 5 * 5)
        return false;
    *lc = b % 9;
    unsigned rem = b / 9;
    *lp = rem % 5;
    *pb = rem / 5;
    return *lc + *lp <= 4;
}

int xz_detect_format(const uint8_t *in, size_t in_size)
{
    if (in_size >= 6 && memcmp(in, XZ_HEADER_MAGIC, 6) == 0)
        return XZF_XZ;

    if (in_size >= 4 && memcmp(in, "LZIP", 4) == 0)
        return XZF_LZIP;

    if (in_size >= 13) {
        unsigned lc, lp, pb;
        if (lzma_props_valid(in[0], &lc, &lp, &pb)) {
            uint32_t dict = get_le32(in + 1);
            if (dict >= 4096 && dict <= (UINT32_C(1536) << 20))
                return XZF_LZMA;
        }
    }

    return XZF_UNKNOWN;
}

/* ---------------------------------------------------------------- */
/* .lzma (alone) decoding                                            */
/* ---------------------------------------------------------------- */

int xz_decode_lzma(const uint8_t *in, size_t in_size, xz_dec_result *res)
{
    res_init(res);
    res->format = XZF_LZMA;

    if (in_size < 13) {
        res->code = in_size == 0 ? XZD_FORMAT : XZD_EOF;
        return res->code;
    }

    unsigned lc, lp, pb;
    if (!lzma_props_valid(in[0], &lc, &lp, &pb)) {
        res->code = XZD_FORMAT;
        return res->code;
    }

    uint32_t dict = get_le32(in + 1);
    uint64_t unpack_size = get_le64(in + 5);

    size_t cap = unpack_size != UINT64_MAX
            ? (size_t)unpack_size
            : in_size * 4 + (1 << 20);
    uint8_t *buf = malloc(cap + 1);
    if (buf == NULL) {
        res->code = XZD_DATA;
        return res->code;
    }

    size_t in_pos = 13;
    size_t out_len = 0;
    int lzret;
    for (;;) {
        lzret = lzma1_decode(in, in_size, &in_pos, buf, cap, &out_len,
                             dict, lc, lp, pb, unpack_size);
        if (lzret != LZD_BUF)
            break;
        cap *= 2;
        uint8_t *nbuf = realloc(buf, cap + 1);
        if (nbuf == NULL) {
            lzret = LZD_DATA;
            break;
        }
        buf = nbuf;
        in_pos = 13;
        out_len = 0;
    }

    if (lzret == LZD_EOF) {
        res->out = buf;
        res->out_size = out_len;
        res->code = XZD_EOF;
        res->consumed = in_pos;
        return res->code;
    }
    if (lzret != LZD_OK) {
        free(buf);
        res->code = lzret == LZD_OPTIONS ? XZD_OPTIONS : XZD_DATA;
        res->consumed = in_pos;
        return res->code;
    }

    res->out = buf;
    res->out_size = out_len;
    res->consumed = in_pos;
    if (in_pos < in_size)
        res->trailing_garbage = true;
    res->code = XZD_OK;
    return XZD_OK;
}

/* ---------------------------------------------------------------- */
/* .lz (lzip) decoding                                               */
/* ---------------------------------------------------------------- */

int xz_decode_lzip(const uint8_t *in, size_t in_size, xz_dec_result *res)
{
    res_init(res);
    res->format = XZF_LZIP;

    size_t p = 0;
    int ret = XZD_OK;

    for (;;) {
        if (in_size - p < 6) {
            ret = p == 0 ? XZD_FORMAT : XZD_EOF;
            break;
        }
        if (memcmp(in + p, "LZIP", 4) != 0) {
            ret = p == 0 ? XZD_FORMAT : XZD_DATA;
            break;
        }
        size_t member_start = p;
        if (in[p + 4] != 1) {
            ret = XZD_OPTIONS;
            break;
        }
        uint8_t coded_dict = in[p + 5];
        uint32_t dict = UINT32_C(1) << (coded_dict & 0x1F);
        if (coded_dict & 0x20)
            dict -= dict / 16;
        p += 6;

        /* The trailer holds the uncompressed size; decode LZMA1 until
         * that much output is produced. We don't know the payload size
         * in advance, so decode until the LZMA stream ends exactly at
         * the size recorded in the trailer -- but the trailer is at the
         * end, which we don't know yet. Decode with unknown size first:
         * lzip LZMA streams carry no end marker, so instead we must
         * find the trailer. Strategy: the LZMA stream end is detected
         * by the range decoder having consumed its bytes after
         * producing the trailer's data size. Since we cannot know it
         * ahead, decode progressively: try to decode assuming the data
         * size found in a candidate trailer located by scanning is
         * overkill. Instead: decode with growing output until the LZMA
         * decoder says it needs more input or finished; lzip payloads
         * are terminated by the range coder flush, detectable only via
         * the trailer. Practical approach: decode with unpack_size
         * unknown is impossible; so we scan: the member size in the
         * trailer tells where it ends. Try every 20-byte window near
         * the end is not robust either.
         *
         * In practice the lzip decoder in xz decodes the LZMA stream
         * and stops when the decoder signals the end of the stream
         * (the range coder's final bytes); the trailer then must match.
         * Our lzma1_decode with unpack_size == UINT64_MAX requires an
         * end marker which lzip does not write. So here we require the
         * caller-facing convention: decode until output stops growing.
         *
         * This is handled by decoding with a provisional unknown size
         * and treating "input exhausted mid-symbol at a flush boundary"
         * as end: our lzma1_decode reports LZD_EOF with out_len set in
         * that case. We then expect the 20-byte trailer.
         */
        size_t cap = (in_size - p) * 4 + (1 << 20);
        uint8_t *buf = malloc(cap + 1);
        if (buf == NULL) {
            ret = XZD_DATA;
            break;
        }
        size_t in_pos = p;
        size_t out_len = 0;
        int lzret;
        for (;;) {
            lzret = lzma1_decode(in, in_size, &in_pos, buf, cap,
                                 &out_len, dict, 3, 0, 2, UINT64_MAX);
            if (lzret != LZD_BUF)
                break;
            cap *= 2;
            uint8_t *nbuf = realloc(buf, cap + 1);
            if (nbuf == NULL) {
                lzret = LZD_DATA;
                break;
            }
            buf = nbuf;
            in_pos = p;
            out_len = 0;
        }

        if (lzret != LZD_OK && lzret != LZD_EOF) {
            free(buf);
            ret = XZD_DATA;
            break;
        }

        /* Trailer: CRC32 (4), data size (8), member size (8). */
        if (in_size - in_pos < 20) {
            free(buf);
            ret = XZD_EOF;
            break;
        }
        uint64_t data_size = get_le64(in + in_pos + 4);
        uint64_t member_size = get_le64(in + in_pos + 12);
        uint8_t crc[4];
        check_compute(CHECK_ID_CRC32, buf, out_len, crc);

        bool ok = data_size == out_len
                && member_size == (uint64_t)(in_pos - member_start) + 20
                && get_le32(in + in_pos) == get_le32(crc);
        if (!ok) {
            free(buf);
            ret = lzret == LZD_EOF ? XZD_EOF : XZD_DATA;
            break;
        }

        if (!res_append(res, buf, out_len)) {
            free(buf);
            ret = XZD_DATA;
            break;
        }
        free(buf);
        p = in_pos + 20;

        if (p == in_size)
            break;
        /* Another member may follow. */
    }

    res->consumed = p;
    res->code = ret;
    return ret;
}

/*
 * Integrity checks: CRC32 (IEEE), CRC64 (ECMA-182), SHA-256.
 * See doc/xz-file-format.txt section 6.
 */
#include <string.h>

#include "check.h"

/* Check sizes for IDs 0x00-0x0F per the .xz spec. */
static const int8_t check_sizes[16] = {
    0,                          /* 0x00 None */
    4, 4, 4,                    /* 0x01 CRC32, 0x02-0x03 reserved */
    8, 8, 8,                    /* 0x04 CRC64, 0x05-0x06 reserved */
    16, 16, 16,                 /* 0x07-0x09 reserved */
    32, 32, 32,                 /* 0x0A SHA-256, 0x0B-0x0C reserved */
    64, 64, 64                  /* 0x0D-0x0F reserved */
};

int check_size_by_id(int id)
{
    if (id < 0 || id > CHECK_ID_MAX)
        return -1;
    return check_sizes[id];
}

bool check_id_supported(int id)
{
    return id == CHECK_ID_NONE || id == CHECK_ID_CRC32
            || id == CHECK_ID_CRC64 || id == CHECK_ID_SHA256;
}

/* ---------------------------------------------------------------- */
/* CRC32: reflected, polynomial 0xEDB88320, init/xorout 0xFFFFFFFF   */
/* ---------------------------------------------------------------- */

static uint32_t crc32_table[256];
static bool crc32_ready = false;

static void crc32_init(void)
{
    for (uint32_t i = 0; i < 256; i++) {
        uint32_t c = i;
        for (int j = 0; j < 8; j++)
            c = (c & 1) ? (c >> 1) ^ UINT32_C(0xEDB88320) : c >> 1;
        crc32_table[i] = c;
    }
    crc32_ready = true;
}

uint32_t my_crc32(const uint8_t *buf, size_t len, uint32_t crc)
{
    if (!crc32_ready)
        crc32_init();

    crc = ~crc;
    for (size_t i = 0; i < len; i++)
        crc = crc32_table[(crc ^ buf[i]) & 0xFF] ^ (crc >> 8);
    return ~crc;
}

/* ---------------------------------------------------------------- */
/* CRC64: reflected, polynomial 0xC96C5795D7870F42, init/xorout ~0   */
/* ---------------------------------------------------------------- */

static uint64_t crc64_table[256];
static bool crc64_ready = false;

static void crc64_init(void)
{
    for (uint32_t i = 0; i < 256; i++) {
        uint64_t c = i;
        for (int j = 0; j < 8; j++)
            c = (c & 1) ? (c >> 1) ^ UINT64_C(0xC96C5795D7870F42)
                        : c >> 1;
        crc64_table[i] = c;
    }
    crc64_ready = true;
}

uint64_t my_crc64(const uint8_t *buf, size_t len, uint64_t crc)
{
    if (!crc64_ready)
        crc64_init();

    crc = ~crc;
    for (size_t i = 0; i < len; i++)
        crc = crc64_table[(crc ^ buf[i]) & 0xFF] ^ (crc >> 8);
    return ~crc;
}

/* ---------------------------------------------------------------- */
/* SHA-256 (FIPS 180-4)                                              */
/* ---------------------------------------------------------------- */

static const uint32_t sha256_k[64] = {
    0x428A2F98, 0x71374491, 0xB5C0FBCF, 0xE9B5DBA5,
    0x3956C25B, 0x59F111F1, 0x923F82A4, 0xAB1C5ED5,
    0xD807AA98, 0x12835B01, 0x243185BE, 0x550C7DC3,
    0x72BE5D74, 0x80DEB1FE, 0x9BDC06A7, 0xC19BF174,
    0xE49B69C1, 0xEFBE4786, 0x0FC19DC6, 0x240CA1CC,
    0x2DE92C6F, 0x4A7484AA, 0x5CB0A9DC, 0x76F988DA,
    0x983E5152, 0xA831C66D, 0xB00327C8, 0xBF597FC7,
    0xC6E00BF3, 0xD5A79147, 0x06CA6351, 0x14292967,
    0x27B70A85, 0x2E1B2138, 0x4D2C6DFC, 0x53380D13,
    0x650A7354, 0x766A0ABB, 0x81C2C92E, 0x92722C85,
    0xA2BFE8A1, 0xA81A664B, 0xC24B8B70, 0xC76C51A3,
    0xD192E819, 0xD6990624, 0xF40E3585, 0x106AA070,
    0x19A4C116, 0x1E376C08, 0x2748774C, 0x34B0BCB5,
    0x391C0CB3, 0x4ED8AA4A, 0x5B9CCA4F, 0x682E6FF3,
    0x748F82EE, 0x78A5636F, 0x84C87814, 0x8CC70208,
    0x90BEFFFA, 0xA4506CEB, 0xBEF9A3F7, 0xC67178F2
};

static uint32_t rotr32(uint32_t x, unsigned n)
{
    return (x >> n) | (x << (32 - n));
}

static void sha256_block(uint32_t state[8], const uint8_t *p)
{
    uint32_t w[64];

    for (int i = 0; i < 16; i++)
        w[i] = ((uint32_t)p[i * 4] << 24) | ((uint32_t)p[i * 4 + 1] << 16)
                | ((uint32_t)p[i * 4 + 2] << 8) | p[i * 4 + 3];

    for (int i = 16; i < 64; i++) {
        uint32_t s0 = rotr32(w[i - 15], 7) ^ rotr32(w[i - 15], 18)
                ^ (w[i - 15] >> 3);
        uint32_t s1 = rotr32(w[i - 2], 17) ^ rotr32(w[i - 2], 19)
                ^ (w[i - 2] >> 10);
        w[i] = w[i - 16] + s0 + w[i - 7] + s1;
    }

    uint32_t a = state[0], b = state[1], c = state[2], d = state[3];
    uint32_t e = state[4], f = state[5], g = state[6], h = state[7];

    for (int i = 0; i < 64; i++) {
        uint32_t s1 = rotr32(e, 6) ^ rotr32(e, 11) ^ rotr32(e, 25);
        uint32_t ch = (e & f) ^ (~e & g);
        uint32_t t1 = h + s1 + ch + sha256_k[i] + w[i];
        uint32_t s0 = rotr32(a, 2) ^ rotr32(a, 13) ^ rotr32(a, 22);
        uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
        uint32_t t2 = s0 + maj;
        h = g;
        g = f;
        f = e;
        e = d + t1;
        d = c;
        c = b;
        b = a;
        a = t1 + t2;
    }

    state[0] += a;
    state[1] += b;
    state[2] += c;
    state[3] += d;
    state[4] += e;
    state[5] += f;
    state[6] += g;
    state[7] += h;
}

void my_sha256(const uint8_t *buf, size_t len, uint8_t out[32])
{
    uint32_t state[8] = {
        0x6A09E667, 0xBB67AE85, 0x3C6EF372, 0xA54FF53A,
        0x510E527F, 0x9B05688C, 0x1F83D9AB, 0x5BE0CD19
    };

    size_t full = len / 64;
    for (size_t i = 0; i < full; i++)
        sha256_block(state, buf + i * 64);

    /* Padding */
    uint8_t tail[128];
    size_t rem = len % 64;
    memcpy(tail, buf + full * 64, rem);
    tail[rem++] = 0x80;
    size_t pad_end = rem <= 56 ? 56 : 120;
    memset(tail + rem, 0, pad_end - rem);
    uint64_t bits = (uint64_t)len * 8;
    for (int i = 0; i < 8; i++)
        tail[pad_end + i] = (uint8_t)(bits >> (56 - i * 8));
    sha256_block(state, tail);
    if (pad_end == 120)
        sha256_block(state, tail + 64);

    for (int i = 0; i < 8; i++) {
        out[i * 4] = (uint8_t)(state[i] >> 24);
        out[i * 4 + 1] = (uint8_t)(state[i] >> 16);
        out[i * 4 + 2] = (uint8_t)(state[i] >> 8);
        out[i * 4 + 3] = (uint8_t)state[i];
    }
}

/* ---------------------------------------------------------------- */

void check_compute(int id, const uint8_t *buf, size_t len, uint8_t *out)
{
    uint64_t v;

    switch (id) {
    case CHECK_ID_CRC32:
        v = my_crc32(buf, len, 0);
        out[0] = (uint8_t)v;
        out[1] = (uint8_t)(v >> 8);
        out[2] = (uint8_t)(v >> 16);
        out[3] = (uint8_t)(v >> 24);
        break;

    case CHECK_ID_CRC64:
        v = my_crc64(buf, len, 0);
        for (int i = 0; i < 8; i++)
            out[i] = (uint8_t)(v >> (i * 8));
        break;

    case CHECK_ID_SHA256:
        my_sha256(buf, len, out);
        break;

    default:
        break;
    }
}

